cd /app && python3 - <<'EOF'
import json, subprocess
d = json.load(open('/tmp/seqs.json'))
inp = d['inp']
site = 215
INS = d['out'][site:site+39]

def rc(s):
    comp = {'a':'t','t':'a','g':'c','c':'g'}
    return ''.join(comp[c] for c in s[::-1])

def tm(seq):
    r = subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq],
                       capture_output=True, text=True)
    return float(r.stdout.strip())

print('oligotm sanity (20-mer):', tm('aagggcgaggagctgttcac'))
fwd_cands, rev_cands = {}, {}
for L1 in range(15,46):
    c = inp[site:site+L1]
    fwd_cands[L1] = tm(c)
for L2 in range(15,46):
    c = rc(inp[site-L2:site])
    rev_cands[L2] = tm(c)

print('FWD anneal (5 tail + this):')
for L1 in range(15,46):
    t = fwd_cands[L1]
    mark = ' <== in range' if 58<=t<=72 else ''
    print(f'  L1={L1:2d} Tm={t:6.2f}{mark}')
print('REV anneal:')
for L2 in range(15,46):
    t = rev_cands[L2]
    mark = ' <== in range' if 58<=t<=72 else ''
    print(f'  L2={L2:2d} Tm={t:6.2f}{mark}')
json.dump({'fwd':fwd_cands,'rev':rev_cands}, open('/tmp/tms.json','w'))
EOF

cd /app && python3 - <<'EOF'
import json
d = json.load(open('/tmp/tms.json'))
fwd = {int(k):v for k,v in d['fwd'].items()}
rev = {int(k):v for k,v in d['rev'].items()}

best=[]
for L1,t1 in fwd.items():
    if not (58<=t1<=72): continue
    for L2,t2 in rev.items():
        if not (58<=t2<=72): continue
        if abs(t1-t2)<=5:
            best.append((abs(t1-t2), L1,t1, L2,t2))
best.sort()
print('top 15 valid (diff, L1,Tm1, L2,Tm2):')
for b in best[:15]:
    print(f'  diff={b[0]:.2f}  L1={b[1]} Tm1={b[2]:.2f}  L2={b[3]} Tm2={b[4]:.2f}')
EOF
